// Use CGAL's Alpha Shape computation
typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef CGAL::Alpha_shape_vertex_base_2<K> Vb;
typedef CGAL::Alpha_shape_face_base_2<K> Fb;
typedef CGAL::Triangulation_data_structure_2<Vb,Fb> Tds;
typedef CGAL::Delaunay_triangulation_2<K,Tds> Triangulation_2;
typedef CGAL::Alpha_shape_2<Triangulation_2> Alpha_shape_2;
typedef Alpha_shape_2::Alpha_shape_edges_iterator Alpha_shape_edges_iterator;

// Convert points to CGAL format
std::vector<K::Point_2> cgal_points;
for (const Point2d& p : points) {
    cgal_points.emplace_back(p.x(), p.y());
}

// Compute alpha shape
Alpha_shape_2 as(cgal_points.begin(), cgal_points.end());
as.set_alpha(alpha);

// Count solid components by finding connected components of alpha-exposed edges
std::vector<bool> visited(points.size(), false);
int solid_components = 0;

for (Alpha_shape_edges_iterator it = as.alpha_shape_edges_begin();
     it != as.alpha_shape_edges_end(); ++it) {
    if (as.classify(*it) == Alpha_shape_2::REGULAR) {
        auto edge = as.segment(*it);
        size_t v1 = std::distance(cgal_points.begin(),
                                 std::find(cgal_points.begin(), cgal_points.end(), edge.source()));
        size_t v2 = std::distance(cgal_points.begin(),
                                 std::find(cgal_points.begin(), cgal_points.end(), edge.target()));

        if (!visited[v1] || !visited[v2]) {
            solid_components++;
            // Simple BFS to mark connected component
            std::queue<size_t> q;
            if (!visited[v1]) {
                q.push(v1);
                visited[v1] = true;
            }
            if (!visited[v2]) {
                q.push(v2);
                visited[v2] = true;
            }

            while (!q.empty()) {
                size_t current = q.front();
                q.pop();

                for (size_t neighbor = 0; neighbor < points.size(); ++neighbor) {
                    if (neighbor != current && !visited[neighbor]) {
                        K::Point_2 p1 = cgal_points[current];
                        K::Point_2 p2 = cgal_points[neighbor];
                        if (as.classify(Alpha_shape_2::Edge(as.triangulation().segment(
                            as.triangulation().vertices_in_edge(
                                as.triangulation().edge(as.triangulation().segment(p1, p2))).first,
                            as.triangulation().vertices_in_edge(
                                as.triangulation().edge(as.triangulation().segment(p1, p2))).second)))
                            == Alpha_shape_2::REGULAR) {
                            visited[neighbor] = true;
                            q.push(neighbor);
                        }
                    }
                }
            }
        }
    }
}

// Handle isolated points (not part of any alpha-exposed edge)
for (size_t i = 0; i < visited.size(); ++i) {
    if (!visited[i]) {
        solid_components++;
    }
}

return solid_components;

